[{"order":1,"type":"heading","text":"Rules Testing using the Firebase Emulator Suite in Firebase Firestore"},{"order":2,"type":"paragraph","text":"Security rules are crucial for protecting your Firebase Firestore data. Testing them locally using the Firebase Emulator Suite allows you to run deterministic tests quickly and safely without modifying your production database."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"Before you begin, ensure you have Node.js installed on your system. You also need to install the Firebase CLI globally and initialize the emulators in your project directory."},{"order":5,"type":"code","text":"npm install -g firebase-tools
firebase init emulators"},{"order":6,"type":"paragraph","text":"During the initialization process, select the Firestore and Emulator options. This will create a firebase.json configuration file and a firestore.rules file in your project root."},{"order":7,"type":"subheading","text":"Writing Security Rules"},{"order":8,"type":"paragraph","text":"Open your firestore.rules file and define a basic rule that allows authenticated users to read and write to their own documents."},{"order":9,"type":"code","text":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /users/{userId} {
      allow read, write: if request.auth != null && request.auth.uid == userId;
    }
  }
}"},{"order":10,"type":"subheading","text":"Setting Up the Test Environment"},{"order":11,"type":"paragraph","text":"To test security rules programmatically, you can use the @firebase/rules-unit-testing library. Install it as a development dependency in your project."},{"order":12,"type":"code","text":"npm install --save-dev @firebase/rules-unit-testing"},{"order":13,"type":"subheading","text":"Writing the Test Suite"},{"order":14,"type":"paragraph","text":"Create a test file, such as firestore.spec.js, and configure the test environment to connect to the Firestore emulator."},{"order":15,"type":"code","text":"const { initializeTestEnvironment, assertFails, assertSucceeds } = require('@firebase/rules-unit-testing');
const fs = require('fs');

let testEnv;

before(async () => {
  testEnv = await initializeTestEnvironment({
    projectId: 'demo-project',
    firestore: {
      rules: fs.readFileSync('firestore.rules', 'utf8'),
    },
  });
});

after(async () => {
  await testEnv.cleanup();
});

afterEach(async () => {
  await testEnv.clearFirestore();
});"},{"order":16,"type":"subheading","text":"Adding Test Cases"},{"order":17,"type":"paragraph","text":"Now, write specific test cases to verify that unauthorized users are blocked and authorized users are allowed."},{"order":18,"type":"code","text":"describe('Firestore Security Rules', () => {
  it('should deny unauthenticated users access to user documents', async () => {
    const db = testEnv.unauthenticatedContext().firestore();
    const userDoc = db.collection('users').doc('alice');
    await assertFails(userDoc.set({ name: 'Alice' }));
  });

  it('should allow authenticated users to write to their own document', async () => {
    const db = testEnv.authenticatedContext('alice').firestore();
    const userDoc = db.collection('users').doc('alice');
    await assertSucceeds(userDoc.set({ name: 'Alice' }));
  });

  it('should deny users writing to another user document', async () => {
    const db = testEnv.authenticatedContext('bob').firestore();
    const userDoc = db.collection('users').doc('alice');
    await assertFails(userDoc.set({ name: 'Alice' }));
  });
});"},{"order":19,"type":"subheading","text":"Running the Tests"},{"order":20,"type":"paragraph","text":"You can run your tests using your preferred test runner like Mocha. The Firebase rules unit testing library automatically spins up and tears down the emulator instance during test execution if configured properly, or you can start the emulator manually using the CLI."},{"order":21,"type":"code","text":"firebase emulators:exec --only firestore 'mocha firestore.spec.js'"},{"order":22,"type":"subheading","text":"Best Practices"},{"order":23,"type":"bullet_point","text":"Always clear your Firestore data between tests using clearFirestore() to ensure test isolation."},{"order":24,"type":"bullet_point","text":"Use the demo-project prefix for your project ID when testing locally to avoid accidental writes to production."},{"order":25,"type":"bullet_point","text":"Integrate rule testing into your CI/CD pipeline to automatically validate rules on every pull request."}]
